# -*- coding: utf-8 -*-
import json, os
M = r"f:/Programs/Slay-the-spire-2-Mods-traduction/_translation_work/pendientes/Sts2ModAlice/esp"
def patch(fn, ov):
    p = os.path.join(M, fn); d = json.load(open(p, encoding="utf-8-sig")); d.update(ov)
    json.dump(d, open(p, "w", encoding="utf-8"), ensure_ascii=False, indent=2)

